394	   * Main program loop for DirectoryScanner. Runs {@link reconcile()} and
395	   * handles any exceptions.
396	   */
397	  @Override
398	  public void run() {
399	    if (!shouldRun.get()) {
400	      // shutdown has been activated
401	      LOG.warn(
402	          "This cycle terminating immediately because 'shouldRun' has been deactivated");
403	      return;
404	    }
405	    try {
406	      reconcile();
407	    } catch (Exception e) {
408	      // Log and continue - allows Executor to run again next cycle
409	      LOG.error(
410	          "Exception during DirectoryScanner execution - will continue next cycle",
411	          e);
