421	  /**
422	   * Stops the directory scanner. This method will wait for 1 minute for the
423	   * main thread to exit and an additional 1 minute for the report compilation
424	   * threads to exit. If a thread does not exit in that time period, it is left
425	   * running, and an error is logged.
426	   */
427	  void shutdown() {
428	    LOG.info("Shutdown has been called");
429	    if (!shouldRun.getAndSet(false)) {
430	      LOG.warn("Shutdown has been called, but periodic scanner not started");
431	    }
432	    if (masterThread != null) {
433	      masterThread.shutdown();
434	    }
435	    if (reportCompileThreadPool != null) {
436	      reportCompileThreadPool.shutdownNow();
437	    }
438	    if (masterThread != null) {
439	      try {
440	        masterThread.awaitTermination(1, TimeUnit.MINUTES);
441	      } catch (InterruptedException e) {
442	        LOG.error(
443	            "interrupted while waiting for masterThread to " + "terminate", e);
444	      }
445	    }
446	    if (reportCompileThreadPool != null) {
447	      try {
448	        reportCompileThreadPool.awaitTermination(1, TimeUnit.MINUTES);
449	      } catch (InterruptedException e) {
450	        LOG.error("interrupted while waiting for reportCompileThreadPool to "
451	            + "terminate", e);
452	      }
453	    }
454	    if (!retainDiffs) {
455	      clear();
456	    }
457	  }
