460	   * Reconcile differences between disk and in-memory blocks
461	   */
462	  @VisibleForTesting
463	  public void reconcile() throws IOException {
464	    LOG.debug("reconcile start DirectoryScanning");
465	    scan();
466	
467	    // HDFS-14476: run checkAndUpdate with batch to avoid holding the lock too
468	    // long
469	    int loopCount = 0;
470	    synchronized (diffs) {
471	      for (final Map.Entry<String, ScanInfo> entry : diffs.getEntries()) {
472	        dataset.checkAndUpdate(entry.getKey(), entry.getValue());
473	
474	        if (loopCount % reconcileBlocksBatchSize == 0) {
475	          try {
476	            Thread.sleep(reconcileBlocksBatchInterval);
477	          } catch (InterruptedException e) {
478	            // do nothing
479	          }
480	        }
481	        loopCount++;
482	      }
483	    }
484	
485	    if (!retainDiffs) {
486	      clear();
487	    }
488	  }
