490	  /**
491	   * Scan for the differences between disk and in-memory blocks Scan only the
492	   * "finalized blocks" lists of both disk and memory.
493	   */
494	  private void scan() {
495	    BlockPoolReport blockPoolReport = new BlockPoolReport();
496	
497	    clear();
498	
499	    Collection<ScanInfoVolumeReport> volumeReports = getVolumeReports();
500	    for (ScanInfoVolumeReport volumeReport : volumeReports) {
501	      for (String blockPoolId : volumeReport.getBlockPoolIds()) {
502	        List<ScanInfo> scanInfos = volumeReport.getScanInfo(blockPoolId);
503	        blockPoolReport.addAll(blockPoolId, scanInfos);
504	      }
505	    }
506	
507	    // Pre-sort the reports outside of the lock
508	    blockPoolReport.sortBlocks();
509	
510	    for (final String bpid : blockPoolReport.getBlockPoolIds()) {
511	      List<ScanInfo> blockpoolReport = blockPoolReport.getScanInfo(bpid);
512	
513	      Stats statsRecord = new Stats(bpid);
514	      stats.put(bpid, statsRecord);
515	      Collection<ScanInfo> diffRecord = new ArrayList<>();
516	
517	      statsRecord.totalBlocks = blockpoolReport.size();
518	      final List<ReplicaInfo> bl = dataset.getFinalizedBlocks(bpid);
519	      Collections.sort(bl); // Sort based on blockId
520	
521	      int d = 0; // index for blockpoolReport
522	      int m = 0; // index for memReprot
523	      while (m < bl.size() && d < blockpoolReport.size()) {
524	        ReplicaInfo memBlock = bl.get(m);
525	        ScanInfo info = blockpoolReport.get(d);
526	        if (info.getBlockId() < memBlock.getBlockId()) {
527	          if (!dataset.isDeletingBlock(bpid, info.getBlockId())) {
528	            // Block is missing in memory
529	            statsRecord.missingMemoryBlocks++;
530	            addDifference(diffRecord, statsRecord, info);
531	          }
532	          d++;
533	          continue;
534	        }
535	        if (info.getBlockId() > memBlock.getBlockId()) {
536	          // Block is missing on the disk
537	          addDifference(diffRecord, statsRecord, memBlock.getBlockId(),
538	              info.getVolume());
539	          m++;
540	          continue;
541	        }
542	        // Block file and/or metadata file exists on the disk
543	        // Block exists in memory
544	        if (info.getBlockFile() == null) {
545	          // Block metadata file exits and block file is missing
546	          addDifference(diffRecord, statsRecord, info);
547	        } else if (info.getGenStamp() != memBlock.getGenerationStamp()
548	            || info.getBlockLength() != memBlock.getNumBytes()) {
549	          // Block metadata file is missing or has wrong generation stamp,
550	          // or block file length is different than expected
551	          statsRecord.mismatchBlocks++;
552	          addDifference(diffRecord, statsRecord, info);
553	        } else if (memBlock.compareWith(info) != 0) {
554	          // volumeMap record and on-disk files do not match.
555	          statsRecord.duplicateBlocks++;
556	          addDifference(diffRecord, statsRecord, info);
557	        }
558	        d++;
559	
560	        if (d < blockpoolReport.size()) {
561	          // There may be multiple on-disk records for the same block, do not
562	          // increment the memory record pointer if so.
563	          ScanInfo nextInfo = blockpoolReport.get(d);
564	          if (nextInfo.getBlockId() != info.getBlockId()) {
565	            ++m;
566	          }
567	        } else {
568	          ++m;
569	        }
570	      }
571	      while (m < bl.size()) {
572	        ReplicaInfo current = bl.get(m++);
573	        addDifference(diffRecord, statsRecord, current.getBlockId(),
574	            current.getVolume());
575	      }
576	      while (d < blockpoolReport.size()) {
577	        if (!dataset.isDeletingBlock(bpid,
578	            blockpoolReport.get(d).getBlockId())) {
579	          statsRecord.missingMemoryBlocks++;
580	          addDifference(diffRecord, statsRecord, blockpoolReport.get(d));
581	        }
582	        d++;
583	      }
584	      synchronized (diffs) {
585	        diffs.addAll(bpid, diffRecord);
586	      }
587	      LOG.info("Scan Results: {}", statsRecord);
588	    }
589	  }
