627	  @VisibleForTesting
628	  public Collection<ScanInfoVolumeReport> getVolumeReports() {
629	    List<ScanInfoVolumeReport> volReports = new ArrayList<>();
630	    List<Future<ScanInfoVolumeReport>> compilersInProgress = new ArrayList<>();
631	
632	    // First get list of data directories
633	    try (FsDatasetSpi.FsVolumeReferences volumes =
634	        dataset.getFsVolumeReferences()) {
635	
636	      for (final FsVolumeSpi volume : volumes) {
637	        // Disable scanning PROVIDED volumes to keep overhead low
638	        if (volume.getStorageType() != StorageType.PROVIDED) {
639	          ReportCompiler reportCompiler = new ReportCompiler(volume);
640	          Future<ScanInfoVolumeReport> result =
641	              reportCompileThreadPool.submit(reportCompiler);
642	          compilersInProgress.add(result);
643	        }
644	      }
645	
646	      for (Future<ScanInfoVolumeReport> future : compilersInProgress) {
647	        try {
648	          final ScanInfoVolumeReport result = future.get();
649	          if (!CollectionUtils.addIgnoreNull(volReports, result)) {
650	            // This compiler thread were interrupted, give up on this run
651	            volReports.clear();
652	            break;
653	          }
654	        } catch (Exception ex) {
655	          LOG.warn("Error compiling report. Continuing.", ex);
656	        }
657	      }
658	    } catch (IOException e) {
659	      LOG.error("Unexpected IOException by closing FsVolumeReference", e);
660	    }
661	
662	    return volReports;
663	  }
