665	  /**
666	   * The ReportCompiler class encapsulates the process of searching a datanode's
667	   * disks for block information. It operates by performing a DFS of the volume
668	   * to discover block information.
669	   *
670	   * When the ReportCompiler discovers block information, it create a new
671	   * ScanInfo object for it and adds that object to its report list. The report
672	   * list is returned by the {@link #call()} method.
673	   */
674	  public class ReportCompiler implements Callable<ScanInfoVolumeReport> {
675	    private final FsVolumeSpi volume;
676	    // Variable for tracking time spent running for throttling purposes
677	    private final StopWatch throttleTimer = new StopWatch();
678	    // Variable for tracking time spent running and waiting for testing
679	    // purposes
680	    private final StopWatch perfTimer = new StopWatch();
681	
682	    /**
683	     * Create a report compiler for the given volume.
684	     *
685	     * @param volume the target volume
686	     */
687	    public ReportCompiler(FsVolumeSpi volume) {
688	      this.volume = volume;
689	    }
690	
691	    /**
692	     * Run this report compiler thread.
693	     *
694	     * @return the block info report list
695	     * @throws IOException if the block pool is not found
696	     */
697	    @Override
698	    public ScanInfoVolumeReport call() throws IOException {
699	      String[] bpList = volume.getBlockPoolList();
700	      ScanInfoVolumeReport result =
701	          new ScanInfoVolumeReport(volume, Arrays.asList(bpList));
702	      perfTimer.start();
703	      throttleTimer.start();
704	      for (String bpid : bpList) {
705	        List<ScanInfo> report = new ArrayList<>(DEFAULT_MAP_SIZE);
706	
707	        perfTimer.reset().start();
708	        throttleTimer.reset().start();
709	
710	        try {
711	          // ScanInfos are added directly to 'report' list
712	          volume.compileReport(bpid, report, this);
713	          result.addAll(bpid, report);
714	        } catch (InterruptedException ex) {
715	          // Exit quickly and flag the scanner to do the same
716	          result = null;
717	          break;
718	        }
719	      }
720	      LOG.trace("Scanner volume report: {}", result);
721	      return result;
722	    }
723	
724	    /**
725	     * Called by the thread before each potential disk scan so that a pause can
726	     * be optionally inserted to limit the number of scans per second. The limit
727	     * is controlled by
728	     * {@link DFSConfigKeys#DFS_DATANODE_DIRECTORYSCAN_THROTTLE_LIMIT_MS_PER_SEC_KEY}.
729	     */
730	    public void throttle() throws InterruptedException {
731	      accumulateTimeRunning();
732	
733	      if (throttleLimitMsPerSec > 0L) {
734	        final long runningTime = throttleTimer.now(TimeUnit.MILLISECONDS);
735	        if (runningTime >= throttleLimitMsPerSec) {
736	          final long sleepTime;
737	          if (runningTime >= 1000L) {
738	            LOG.warn("Unable to throttle within the second. Blocking for 1s.");
739	            sleepTime = 1000L;
740	          } else {
741	            // Sleep for the expected time plus any time processing ran over
742	            final long overTime = runningTime - throttleLimitMsPerSec;
743	            sleepTime = (1000L - throttleLimitMsPerSec) + overTime;
744	          }
745	          Thread.sleep(sleepTime);
746	          throttleTimer.reset().start();
747	        }
748	        accumulateTimeWaiting();
749	      }
750	    }
751	
752	    /**
753	     * Helper method to measure time running.
754	     */
755	    private void accumulateTimeRunning() {
756	      timeRunningMs.getAndAdd(perfTimer.now(TimeUnit.MILLISECONDS));
757	      perfTimer.reset().start();
758	    }
759	
760	    /**
761	     * Helper method to measure time waiting.
762	     */
763	    private void accumulateTimeWaiting() {
764	      timeWaitingMs.getAndAdd(perfTimer.now(TimeUnit.MILLISECONDS));
765	      perfTimer.reset().start();
766	    }
767	  }
768	}
